import {
  Box,
  Card,
  CardMedia,
  CircularProgress,
  debounce,
  Dialog,
  DialogContent,
  DialogTitle,
  Drawer,
  Grid,
  IconButton,
  Menu,
  MenuItem,
  Pagination,
  Select,
  Stack,
  Tab,
  Tabs,
  Typography,
  useTheme
} from '@mui/material';
import { useTranslation } from 'react-i18next';
import CustomDatagrid2, {
  CustomDatagridColumn2
} from '../components/CustomDatagrid2';
import Part from '../../../models/owns/part';
import {
  addPart,
  clearSinglePart,
  deletePart,
  editPart,
  getParts,
  getSinglePart
} from '../../../slices/part';
import ConfirmDialog from '../components/ConfirmDialog';
import { useDispatch, useSelector } from '../../../store';
import * as React from 'react';
import { ChangeEvent, useContext, useEffect, useMemo, useState } from 'react';
import * as Yup from 'yup';
import Form from '../components/form';
import { getCustomFieldsValues, IField } from '../type';
import PartDetails from './PartDetails';
import { useNavigate, useParams } from 'react-router-dom';
import { isNumeric } from '../../../utils/validators';
import {
  formatSelect,
  formatSelectMultiple,
  formatCustomFields,
  getFormattedCostPerUnit
} from '../../../utils/formatters';
import { UserMiniDTO } from '../../../models/user';
import UserAvatars from '../components/UserAvatars';
import { CustomSnackBarContext } from '../../../contexts/CustomSnackBarContext';
import { CompanySettingsContext } from '../../../contexts/CompanySettingsContext';
import useAuth from '../../../hooks/useAuth';
import NoRowsMessageWrapper from '../components/NoRowsMessageWrapper';
import {
  getImageAndFiles,
  handleFileUpload,
  onSearchQueryChange
} from '../../../utils/overall';
import { SearchCriteria, SortDirection } from '../../../models/owns/page';
import { useExport, ExportEntityType } from '../../../hooks/useExport';
import MoreVertTwoToneIcon from '@mui/icons-material/MoreVertTwoTone';
import { PermissionEntity } from '../../../models/owns/role';
import SearchInput from '../components/SearchInput';
import { PlanFeature } from '../../../models/owns/subscriptionPlan';
import { createColumnHelper } from '@tanstack/react-table';
import useTableState from '../../../hooks/useTableState';
import { CategoryMiniDTO } from '../../../models/owns/category';
import { getErrorMessage } from '../../../utils/api';
import { getPartUrl } from '../../../utils/urlPaths';
import { getCustomFields } from '../../../slices/customField';
import { CustomFieldEntityType } from '../../../models/owns/customField';
import { getCustomFieldsRequiredShape, getCustomFieldsIFields } from '../type';

interface PropsType {
  setAction: (p: () => () => void) => void;
}

export const getFormattedQuantityWithUnit = (
  quantity: number,
  unit: string
) => {
  return unit ? quantity + ' ' + unit : quantity;
};

const fieldMapping: Record<string, string> = {
  name: 'name',
  cost: 'cost',
  quantity: 'quantity',
  barcode: 'barcode',
  area: 'area',
  category: 'category.name',
  description: 'description',
  createdAt: 'createdAt',
  openWorkOrders: 'openWorkOrders'
};

const PAGE_SIZE = 12;
const Parts = ({ setAction }: PropsType) => {
  const { t }: { t: any } = useTranslation();
  const [currentTab, setCurrentTab] = useState<string>('list');
  const [openUpdateModal, setOpenUpdateModal] = useState<boolean>(false);
  const [openDrawer, setOpenDrawer] = useState<boolean>(false);
  const { getFormattedDate, uploadFiles, getFormattedCurrency } = useContext(
    CompanySettingsContext
  );
  const { parts, loadingGet, singlePart } = useSelector((state) => state.parts);
  const { customFields } = useSelector((state) => state.customFields);
  const [openDrawerFromUrl, setOpenDrawerFromUrl] = useState<boolean>(false);
  const [criteria, setCriteria] = useState<SearchCriteria>({
    filterFields: [],
    pageSize: PAGE_SIZE,
    pageNum: 0,
    direction: 'DESC'
  });

  // Use the table state hook for TanStack Table
  const {
    sorting,
    setSorting,
    pagination,
    setPagination,
    columnOrder,
    setColumnOrder,
    columnSizing,
    setColumnSizing,
    columnVisibility,
    setColumnVisibility,
    pinnedColumns,
    setPinnedColumns
  } = useTableState({
    prefix: 'parts',
    initialSorting: [],
    initialPagination: {
      pageSize: criteria.pageSize,
      pageIndex: criteria.pageNum
    },
    setCriteria,
    fieldMapping
  });
  const [openDelete, setOpenDelete] = useState<boolean>(false);
  const [openAddModal, setOpenAddModal] = useState<boolean>(false);
  const [copyPartData, setCopyPartData] = useState<Part | null>(null);
  const [currentPart, setCurrentPart] = useState<Part>();
  const {
    getFilteredFields,
    hasViewPermission,
    hasViewOtherPermission,
    hasFeature
  } = useAuth();
  const { partId } = useParams();
  const dispatch = useDispatch();
  const { showSnackBar } = useContext(CustomSnackBarContext);
  const { exportEntity, loadingExport } = useExport();
  const [anchorEl, setAnchorEl] = React.useState<null | HTMLElement>(null);
  const openMenu = Boolean(anchorEl);
  const navigate = useNavigate();
  const onQueryChange = (event) => {
    onSearchQueryChange<Part>(event, criteria, setCriteria, [
      'name',
      'description',
      'additionalInfos',
      'area',
      'barcode',
      'customFieldValues.value'
    ]);
  };
  const debouncedQueryChange = useMemo(() => debounce(onQueryChange, 1300), []);

  const handleOpenMenu = (event: React.MouseEvent<HTMLButtonElement>) => {
    setAnchorEl(event.currentTarget);
  };
  const handleCloseMenu = () => {
    setAnchorEl(null);
  };

  const handleOpenUpdate = () => {
    setOpenUpdateModal(true);
  };

  const handleDelete = (id: number) => {
    handleCloseDetails();
    dispatch(deletePart(id)).then(onDeleteSuccess).catch(onDeleteFailure);
    setOpenDelete(false);
  };
  const tabs = [
    { value: 'list', label: t('list_view') },
    { value: 'card', label: t('card_view') }
  ];
  const theme = useTheme();
  const handleCopyPart = (part: Part) => {
    setCopyPartData(part);
    setOpenAddModal(true);
  };
  const onCreationSuccess = (createdPart: Part) => {
    setOpenAddModal(false);
    showSnackBar(t('part_create_success'), 'success');
    if (copyPartData && createdPart) {
      navigate(getPartUrl(createdPart.id));
    }
    setCopyPartData(null);
  };
  const onCreationFailure = (err) =>
    showSnackBar(getErrorMessage(err, t('part_create_failure')), 'error');
  const onEditSuccess = () => {
    setOpenUpdateModal(false);
    showSnackBar(t('changes_saved_success'), 'success');
  };
  const onEditFailure = (err) => showSnackBar(t('part_edit_failure'), 'error');
  const onDeleteSuccess = () => {
    showSnackBar(t('part_delete_success'), 'success');
  };
  const onDeleteFailure = (err) =>
    showSnackBar(t('part_delete_failure'), 'error');
  useEffect(() => {
    const handleOpenModal = () => setOpenAddModal(true);
    setAction(() => handleOpenModal);
  }, []);

  const handleOpenDrawer = (part: Part) => {
    setCurrentPart(part);
    window.history.replaceState(
      null,
      'Part details',
      `/app/inventory/parts/${part.id}`
    );
    setOpenDrawer(true);
  };
  useEffect(() => {
    if (partId && isNumeric(partId)) {
      dispatch(getSinglePart(Number(partId)));
    }
  }, [partId]);

  useEffect(() => {
    dispatch(getParts(criteria));
  }, [criteria]);

  //see changes in ui on edit
  useEffect(() => {
    if (singlePart || parts.content.length) {
      const currentInContent = parts.content.find(
        (part) => part.id === currentPart?.id
      );
      const updatedPart = currentInContent ?? singlePart;
      if (updatedPart) {
        if (openDrawerFromUrl) {
          setCurrentPart(updatedPart);
        } else {
          handleOpenDrawer(updatedPart);
          setOpenDrawerFromUrl(true);
        }
      }
    }
    return () => {
      dispatch(clearSinglePart());
    };
  }, [singlePart, parts]);

  useEffect(() => {
    if ((openAddModal || openUpdateModal) && !customFields.length) {
      dispatch(getCustomFields());
    }
  }, [openAddModal, openUpdateModal]);

  const handleTabsChange = (_event: ChangeEvent<{}>, value: string): void => {
    setCurrentTab(value);
  };
  const handleOpenDetails = (id: number) => {
    const foundPart = parts.content.find((part) => part.id === id);
    if (foundPart) {
      handleOpenDrawer(foundPart);
    }
  };
  const handleCloseDetails = () => {
    window.history.replaceState(null, 'Part', `/app/inventory/parts`);
    setOpenDrawer(false);
  };
  const getPartFormValues = (entity: Part | null | undefined) => ({
    ...entity,
    category: entity?.category
      ? { label: entity.category.name, value: entity.category.id }
      : null,
    assignedTo:
      entity?.assignedTo?.map((user) => ({
        label: `${user.firstName} ${user.lastName}`,
        value: user.id.toString()
      })) ?? [],
    teams:
      entity?.teams?.map((team) => ({
        label: team.name,
        value: team.id.toString()
      })) ?? [],
    vendors:
      entity?.vendors?.map((vendor) => ({
        label: vendor.companyName,
        value: vendor.id.toString()
      })) ?? [],
    customers:
      entity?.customers?.map((customer) => ({
        label: customer.name,
        value: customer.id.toString()
      })) ?? [],
    ...getCustomFieldsValues(entity)
  });
  const formatValues = (values) => {
    const newValues = { ...values };
    newValues.assignedTo = formatSelectMultiple(newValues.assignedTo);
    newValues.teams = formatSelectMultiple(newValues.teams);
    newValues.customers = formatSelectMultiple(newValues.customers);
    newValues.vendors = formatSelectMultiple(newValues.vendors);
    newValues.category = formatSelect(newValues.category);
    return formatCustomFields(newValues);
  };

  const columnHelper = createColumnHelper<Part>();

  const columns: CustomDatagridColumn2<Part>[] = [
    columnHelper.accessor('name', {
      id: 'name',
      header: () => t('name'),
      cell: (info) => <Box sx={{ fontWeight: 'bold' }}>{info.getValue()}</Box>,
      size: 150
    }),
    columnHelper.accessor('cost', {
      id: 'cost',
      header: () => t('cost'),
      cell: (info) =>
        getFormattedCostPerUnit(
          info.getValue(),
          info.row.original.unit,
          getFormattedCurrency
        ),
      size: 150
    }),
    columnHelper.accessor('quantity', {
      id: 'quantity',
      header: () => t('quantity'),
      cell: (info) => {
        const quantity = info.getValue();
        const row = info.row.original;
        return (
          <Box sx={quantity < row.minQuantity ? { color: 'red' } : {}}>
            {getFormattedQuantityWithUnit(quantity, row.unit)}{' '}
            {quantity < row.minQuantity && t('(Running Low !)')}
          </Box>
        );
      },
      size: 150
    }),
    columnHelper.accessor('barcode', {
      id: 'barcode',
      header: () => t('barcode'),
      cell: (info) => info.getValue() || '',
      size: 150
    }),
    columnHelper.accessor('area', {
      id: 'area',
      header: () => t('area'),
      cell: (info) => info.getValue() || '',
      size: 150
    }),
    columnHelper.accessor((row) => row.category?.name, {
      id: 'category',
      header: () => t('category'),
      cell: (info) => info.getValue() || '',
      size: 150
    }),
    columnHelper.accessor('description', {
      id: 'description',
      header: () => t('description'),
      cell: (info) => info.getValue() || '',
      size: 300
    }),
    columnHelper.accessor('assignedTo', {
      id: 'assignedTo',
      header: () => t('assigned_to'),
      cell: (info) => <UserAvatars users={info.getValue()} />,
      size: 170
    }),
    columnHelper.accessor('createdAt', {
      id: 'createdAt',
      header: () => t('created_at'),
      cell: (info) => getFormattedDate(info.getValue()),
      size: 150
    })
    // columnHelper.accessor('openWorkOrders', {
    //   id: 'openWorkOrders',
    //   header: () => t('open_wo'),
    //   cell: (info) => info.getValue() || '',
    //   size: 150
    // })
  ];
  const fields: Array<IField> = [
    {
      name: 'name',
      type: 'text',
      label: t('name'),
      placeholder: t('enter_part_name'),
      required: true
    },
    {
      name: 'description',
      type: 'text',
      label: t('description'),
      placeholder: t('description'),
      multiple: true
    },
    {
      name: 'category',
      type: 'select',
      type2: 'category',
      category: 'part-categories',
      label: t('category'),
      placeholder: t('enter_part_category')
    },
    {
      name: 'cost',
      type: 'number',
      label: t('cost'),
      placeholder: t('enter_part_cost')
    },
    {
      name: 'quantity',
      type: 'number',
      label: t('quantity'),
      placeholder: t('enter_part_quantity')
    },
    {
      name: 'unit',
      type: 'text',
      label: t('unit'),
      placeholder: t('unit_of_measurement')
    },
    {
      name: 'minQuantity',
      type: 'number',
      label: t('minimum_quantity'),
      placeholder: t('enter_part_minimum_quantity')
    },
    {
      name: 'nonStock',
      type: 'checkbox',
      label: t('non_stock')
    },
    {
      name: 'barcode',
      type: 'text',
      label: t('barcode'),
      placeholder: t('enter_part_barcode')
    },
    {
      name: 'area',
      type: 'text',
      label: t('area'),
      placeholder: t('enter_part_area')
    },
    {
      name: 'additionalInfos',
      type: 'text',
      label: t('additional_part_details'),
      placeholder: t('additional_part_details'),
      multiple: true
    },
    {
      name: 'assignedTo',
      type: 'select',
      type2: 'user',
      multiple: true,
      label: t('workers'),
      placeholder: 'Select Workers'
    },
    {
      name: 'teams',
      type: 'select',
      type2: 'team',
      multiple: true,
      label: t('teams'),
      placeholder: 'Select Teams'
    },
    {
      name: 'vendors',
      type: 'select',
      type2: 'vendor',
      multiple: true,
      label: t('vendors'),
      placeholder: 'Select Vendors'
    },
    {
      name: 'customers',
      type: 'select',
      type2: 'customer',
      multiple: true,
      label: t('customers'),
      placeholder: 'Select Customers'
    },
    {
      name: 'image',
      type: 'file',
      label: t('image'),
      fileType: 'image'
    },
    {
      name: 'files',
      type: 'file',
      multiple: true,
      label: t('files')
    },
    ...getCustomFieldsIFields(customFields, CustomFieldEntityType.PART)
  ];
  const shape = {
    name: Yup.string().required(t('required_part_name')),
    ...getCustomFieldsRequiredShape(customFields, CustomFieldEntityType.PART, t)
  };
  const renderPartAddModal = () => (
    <Dialog
      fullWidth
      maxWidth="md"
      open={openAddModal}
      onClose={() => {
        setOpenAddModal(false);
        setCopyPartData(null);
      }}
    >
      <DialogTitle
        sx={{
          p: 3
        }}
      >
        <Typography variant="h4" gutterBottom>
          {copyPartData ? t('copy_part') : t('add_part')}
        </Typography>
        <Typography variant="subtitle2">
          {copyPartData
            ? t('copy_part_description')
            : t('add_part_description')}
        </Typography>
      </DialogTitle>
      <DialogContent
        dividers
        sx={{
          p: 3
        }}
      >
        <Box>
          <Form
            fields={getFilteredFields(fields)}
            validation={Yup.object().shape(shape)}
            submitText={t('create_part')}
            values={
              copyPartData
                ? { ...getPartFormValues(copyPartData), id: null }
                : {}
            }
            onChange={({ field, e }) => {}}
            onSubmit={async (values) => {
              let formattedValues = formatValues(values);
              try {
                const uploadedFiles = await uploadFiles(
                  formattedValues.files,
                  formattedValues.image
                );

                const imageAndFiles = getImageAndFiles(uploadedFiles);
                formattedValues = {
                  ...formattedValues,
                  image: imageAndFiles.image,
                  files: imageAndFiles.files
                };

                const createdPart: Part = await dispatch(
                  addPart(formattedValues)
                );
                onCreationSuccess(createdPart);
              } catch (err) {
                onCreationFailure(err);
                throw err;
              }
            }}
          />
        </Box>
      </DialogContent>
    </Dialog>
  );
  const BasicField = ({
    label,
    value
  }: {
    label: string | number;
    value: string | number;
  }) => {
    return value ? (
      <Grid item xs={12}>
        <Stack spacing={1} direction="row">
          <Typography variant="h6" sx={{ color: theme.colors.alpha.black[70] }}>
            {label}
          </Typography>
          <Typography variant="h6">{value}</Typography>
        </Stack>
      </Grid>
    ) : null;
  };
  const fieldsToRender = (part: Part) => [
    {
      label: t('id'),
      value: part.id
    },
    {
      label: t('category'),
      value: part.category?.name
    },
    {
      label: t('quantity'),
      value: getFormattedQuantityWithUnit(part.quantity, part.unit)
    },
    {
      label: t('cost'),
      value: getFormattedCurrency(part.cost)
    },
    {
      label: t('barcode'),
      value: part.barcode
    },
    {
      label: t('created_at'),
      value: getFormattedDate(part.createdAt)
    }
  ];
  const renderPartUpdateModal = () => (
    <Dialog
      fullWidth
      maxWidth="md"
      open={openUpdateModal}
      onClose={() => setOpenUpdateModal(false)}
    >
      <DialogTitle
        sx={{
          p: 3
        }}
      >
        <Typography variant="h4" gutterBottom>
          {t('update_part')}
        </Typography>
        <Typography variant="subtitle2">
          {t('update_part_description')}
        </Typography>
      </DialogTitle>
      <DialogContent
        dividers
        sx={{
          p: 3
        }}
      >
        <Box>
          <Form
            fields={getFilteredFields(fields)}
            validation={Yup.object().shape(shape)}
            submitText={t('save')}
            values={getPartFormValues(currentPart)}
            onChange={({ field, e }) => {}}
            onSubmit={async (values) => {
              let formattedValues = formatValues(values);
              try {
                const imageAndFiles = await handleFileUpload(
                  {
                    files: formattedValues.files,
                    image: formattedValues.image
                  },
                  uploadFiles
                );

                formattedValues = {
                  ...formattedValues,
                  image: imageAndFiles.image,
                  files: imageAndFiles.files
                };

                await dispatch(editPart(currentPart.id, formattedValues));
                await onEditSuccess();
              } catch (err) {
                onEditFailure(err);
                throw err;
              }
            }}
          />
        </Box>
      </DialogContent>
    </Dialog>
  );
  const renderMenu = () => {
    const exportMenuItems: { entity: ExportEntityType; labelKey: string }[] = [
      { entity: 'parts', labelKey: 'export_parts' },
      { entity: 'part-transactions', labelKey: 'export_part_transactions' }
    ];
    return (
      <Menu
        id="basic-menu"
        anchorEl={anchorEl}
        open={openMenu}
        onClose={handleCloseMenu}
        MenuListProps={{
          'aria-labelledby': 'basic-button'
        }}
      >
        {hasViewOtherPermission(PermissionEntity.PARTS_AND_MULTIPARTS) &&
          exportMenuItems.map(({ entity, labelKey }) => (
            <MenuItem
              key={entity}
              disabled={loadingExport[entity]}
              onClick={async () => {
                try {
                  await exportEntity(entity);
                } catch (error) {
                  showSnackBar(t('Export failed'), 'error');
                }
              }}
            >
              <Stack spacing={2} direction="row">
                {loadingExport[entity] && <CircularProgress size="1rem" />}
                <Typography>{t(labelKey)}</Typography>
              </Stack>
            </MenuItem>
          ))}
        {hasViewPermission(PermissionEntity.SETTINGS) && (
          <MenuItem
            onClick={() => navigate('/app/imports/parts')}
            disabled={!hasFeature(PlanFeature.IMPORT_CSV)}
          >
            {t('to_import')}
          </MenuItem>
        )}
      </Menu>
    );
  };
  return (
    <Box sx={{ p: 2 }}>
      {renderPartAddModal()}
      {renderPartUpdateModal()}
      {renderMenu()}
      <Stack
        mb={1}
        direction="row"
        justifyContent="space-between"
        alignItems="center"
      >
        <Tabs
          onChange={handleTabsChange}
          value={currentTab}
          variant="scrollable"
          scrollButtons="auto"
          textColor="primary"
          indicatorColor="primary"
        >
          {tabs.map((tab) => (
            <Tab key={tab.value} label={tab.label} value={tab.value} />
          ))}
        </Tabs>
        <SearchInput onChange={debouncedQueryChange} />
        <IconButton onClick={handleOpenMenu} color="primary">
          <MoreVertTwoToneIcon />
        </IconButton>
      </Stack>
      {currentTab === 'list' && (
        <CustomDatagrid2
          columns={columns}
          data={parts.content}
          loading={loadingGet}
          pagination={pagination}
          onPaginationChange={setPagination}
          totalRows={parts.totalElements}
          pageSizeOptions={[PAGE_SIZE, PAGE_SIZE * 2, PAGE_SIZE * 4]}
          sorting={sorting}
          onSortingChange={setSorting}
          columnOrder={columnOrder}
          onColumnOrderChange={setColumnOrder}
          columnSizing={columnSizing}
          onColumnSizingChange={setColumnSizing}
          columnVisibility={columnVisibility}
          onColumnVisibilityChange={setColumnVisibility}
          onRowClick={(row) => handleOpenDetails(row.id)}
          noRowsMessage={t('noRows.part.message')}
          noRowsAction={t('noRows.part.action')}
          enableColumnReordering
          enableColumnResizing
          pinnedColumns={pinnedColumns}
          onPinnedColumnsChange={setPinnedColumns}
        />
      )}
      {currentTab === 'card' && (
        <Box>
          <Grid container spacing={2}>
            {parts.content.map((part) => (
              <Grid item xs={12} sm={6} md={4} lg={3} key={part.id}>
                <Card
                  style={{ cursor: 'pointer', height: '100%' }}
                  onClick={() => handleOpenDetails(part.id)}
                >
                  <CardMedia
                    component="img"
                    height="280"
                    image={
                      part.image ? part.image.url : '/static/images/nopic.jpg'
                    }
                    alt={part.name}
                  />
                  <Box sx={{ p: 2 }}>
                    <Typography variant="h4">{part.name}</Typography>
                    <Box sx={{ mt: 1 }}>
                      {fieldsToRender(part).map((field) => (
                        <BasicField
                          key={field.label}
                          label={field.label}
                          value={field.value}
                        />
                      ))}
                    </Box>
                  </Box>
                </Card>
              </Grid>
            ))}
          </Grid>
          <Stack
            direction="row"
            justifyContent="space-between"
            alignItems="center"
            sx={{ mt: 2, mb: 2 }}
          >
            <Typography variant="body2" color="text.secondary">
              {parts.totalElements} {t('total_items')}
            </Typography>
            <Stack direction="row" spacing={2} alignItems="center">
              <Typography variant="body2">{t('items_per_page')}:</Typography>
              <Select
                value={criteria.pageSize}
                onChange={(e) =>
                  setCriteria({
                    ...criteria,
                    pageSize: Number(e.target.value),
                    pageNum: 0
                  })
                }
              >
                {[PAGE_SIZE, PAGE_SIZE * 2, PAGE_SIZE * 4].map((size) => (
                  <MenuItem key={size} value={size}>
                    {size}
                  </MenuItem>
                ))}
              </Select>
              <Pagination
                count={Math.ceil(parts.totalElements / criteria.pageSize)}
                page={criteria.pageNum + 1}
                onChange={(_event, page) =>
                  setCriteria({ ...criteria, pageNum: page - 1 })
                }
                color="primary"
              />
            </Stack>
          </Stack>
        </Box>
      )}
      <Drawer
        anchor="right"
        open={openDrawer}
        onClose={handleCloseDetails}
        PaperProps={{
          sx: { width: { xs: '90%', sm: '70%', md: '50%' } }
        }}
      >
        <PartDetails
          part={currentPart}
          handleOpenUpdate={handleOpenUpdate}
          handleOpenDelete={() => setOpenDelete(true)}
          onCopy={handleCopyPart}
        />
      </Drawer>
      <ConfirmDialog
        open={openDelete}
        onCancel={() => {
          setOpenDelete(false);
          setOpenDrawer(true);
        }}
        onConfirm={() => handleDelete(currentPart?.id)}
        confirmText={t('to_delete')}
        question={t('confirm_delete_part')}
      />
    </Box>
  );
};

export default Parts;
